// MIT. Read-only Wii touchpad input from the launcher's session-scoped mapping.
struct kaliw_pointer_port {int32_t x,y,active,click;};
struct kaliw_pointer_packet {uint32_t magic,sequence,updated;struct kaliw_pointer_port ports[4];};
static HANDLE pointer_mapping;static volatile struct kaliw_pointer_packet*pointer_view;
static struct kaliw_pointer_port pointer_ports[4];
static void pointer_init(void){wchar_t name[160];if(!GetEnvironmentVariableW(L"KALIW_POINTER_MAP",name,160))return;pointer_mapping=OpenFileMappingW(FILE_MAP_READ,FALSE,name);if(pointer_mapping)pointer_view=MapViewOfFile(pointer_mapping,FILE_MAP_READ,0,0,sizeof(struct kaliw_pointer_packet));}
static void pointer_refresh(void){memset(pointer_ports,0,sizeof(pointer_ports));if(!pointer_view)return;uint32_t seq=pointer_view->sequence;MemoryBarrier();if(seq&1)return;struct kaliw_pointer_packet p;memcpy(&p,(const void*)pointer_view,sizeof(p));MemoryBarrier();if(seq!=pointer_view->sequence||p.magic!=0x4b505431||(uint32_t)(GetTickCount()-p.updated)>500)return;for(unsigned i=0;i<4;i++)if(p.ports[i].active==1&&p.ports[i].x>=-32767&&p.ports[i].x<=32767&&p.ports[i].y>=-32767&&p.ports[i].y<=32767){pointer_ports[i]=p.ports[i];pointer_ports[i].click=p.ports[i].click==1;}}
static int16_t wii_input_forward(unsigned port,unsigned device,unsigned index,unsigned id){if(menu_paused||combo_held)return 0;if(port<4&&pointer_ports[port].active){struct kaliw_pointer_port*p=&pointer_ports[port];if(device==RETRO_DEVICE_POINTER&&index==0){if(id==RETRO_DEVICE_ID_POINTER_X)return p->x;if(id==RETRO_DEVICE_ID_POINTER_Y)return p->y;if(id==RETRO_DEVICE_ID_POINTER_PRESSED||id==RETRO_DEVICE_ID_POINTER_COUNT)return 1;if(id==RETRO_DEVICE_ID_POINTER_IS_OFFSCREEN)return 0;}if(device==RETRO_DEVICE_JOYPAD&&p->click){if(id==RETRO_DEVICE_ID_JOYPAD_A)return 1;if(id==RETRO_DEVICE_ID_JOYPAD_MASK)return input_forward(port,device,index,id)|(1<<RETRO_DEVICE_ID_JOYPAD_A);}}return input_forward(port,device,index,id);}
static void pointer_shutdown(void){if(pointer_view)UnmapViewOfFile((const void*)pointer_view);if(pointer_mapping)CloseHandle(pointer_mapping);pointer_view=NULL;pointer_mapping=NULL;memset(pointer_ports,0,sizeof(pointer_ports));}
